INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Different Customs Around the World', 'When you visit a foreign country, it is important to learn about its customs. In some countries, people are supposed to shake hands when they meet. In Japan, people are supposed to bow instead. In some places, friends greet each other with a kiss on the cheek. Time also matters. In Switzerland, you are supposed to be on time. It is impolite to keep others waiting. But in some warm countries, people are more relaxed about time. Knowing these customs helps us make a good first impression. After all, good manners are important everywhere, even if they are different from place to place.', '说明文', 103, '[{"q": "What is important when you visit a foreign country?", "answer": "B", "options": ["To buy clothes.", "To learn about its customs.", "To stay home.", "To bring a gift."], "explanation": "原文:important to learn about its customs"}, {"q": "What are people supposed to do in Japan when they meet?", "answer": "B", "options": ["Wave.", "Bow.", "Kiss.", "Shake hands."], "explanation": "原文:In Japan, people are supposed to bow"}, {"q": "What is the rule about time in Switzerland?", "answer": "A", "options": ["You are supposed to be on time.", "You can be late.", "Time does not matter.", "You must come early."], "explanation": "原文:In Switzerland, you are supposed to be on time"}, {"q": "What is impolite according to the passage?", "answer": "A", "options": ["Keeping others waiting.", "Shaking hands.", "Being early.", "Bowing."], "explanation": "原文:impolite to keep others waiting"}, {"q": "What helps us make a good first impression?", "answer": "C", "options": ["Speaking loudly.", "Being late.", "Knowing these customs.", "Wearing a suit."], "explanation": "原文:helps us make a good first impression"}]'::jsonb, '[{"word": "custom", "cn": "风俗;习俗"}, {"word": "greet", "cn": "打招呼;迎接"}, {"word": "relaxed", "cn": "放松的"}]'::jsonb, 3, '9', 'U10');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Maria''s First Dinner', 'Maria is an exchange student in the US. Last night, she had dinner at an American friend''s house. Maria made a few mistakes because she did not know the customs. First, she arrived late. In the US, you are supposed to arrive on time. Then, she ate the food before everyone else started. You are supposed to wait until everyone is ready. She also greeted her friend''s mother in the wrong way. But her friend''s family was very kind. They were not mad at her. They helped her learn. By the end of the evening, Maria felt much more relaxed. She learned that it is important to learn local customs.', '记叙文', 110, '[{"q": "Where is Maria an exchange student?", "answer": "C", "options": ["In China.", "In Brazil.", "In the US.", "In Japan."], "explanation": "原文:exchange student in the US"}, {"q": "What was Maria''s first mistake?", "answer": "C", "options": ["She ate too much.", "She wore the wrong clothes.", "She arrived late.", "She left early."], "explanation": "原文:she arrived late"}, {"q": "When are you supposed to start eating in the US?", "answer": "C", "options": ["At any time.", "Before everyone.", "When everyone is ready.", "After dinner."], "explanation": "原文:supposed to wait until everyone is ready"}, {"q": "How did her friend''s family feel?", "answer": "B", "options": ["They were sad.", "They were not mad.", "They left.", "They were angry."], "explanation": "原文:They were not mad at her"}, {"q": "What did Maria learn?", "answer": "D", "options": ["Friends are mean.", "The US is far.", "Dinner is hard.", "It is important to learn local customs."], "explanation": "原文:important to learn local customs"}]'::jsonb, '[{"word": "exchange", "cn": "交换"}, {"word": "mad", "cn": "很生气的"}, {"word": "relaxed", "cn": "放松的"}]'::jsonb, 3, '9', 'U10');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Is It OK to Be Late?', 'People in different countries have different ideas about time. Teresa is from Colombia. She says it is OK to be a little late when meeting friends. "We value people more than time," she says. If a friend is late, she does not get mad. Marc is from Switzerland. For him, being on time is very important. "We are the capital of clocks and watches," he says. If someone invites you to dinner at seven, you are supposed to arrive at seven. Both ideas are fine in their own countries. The most important thing is to learn the local custom, so that you do not make others uneasy.', '议论文', 107, '[{"q": "Where is Teresa from?", "answer": "C", "options": ["the US.", "Switzerland.", "Colombia.", "Japan."], "explanation": "原文:Teresa is from Colombia"}, {"q": "What does Teresa value more than time?", "answer": "C", "options": ["Food.", "Money.", "People.", "Clocks."], "explanation": "原文:We value people more than time"}, {"q": "Where is Marc from?", "answer": "B", "options": ["Brazil.", "Switzerland.", "China.", "Colombia."], "explanation": "原文:Marc is from Switzerland"}, {"q": "What is important to Marc?", "answer": "D", "options": ["Being relaxed.", "Being late.", "Being early.", "Being on time."], "explanation": "原文:being on time is very important"}, {"q": "What is the most important thing according to the writer?", "answer": "D", "options": ["To value clocks.", "To be late.", "To be early.", "To learn the local custom."], "explanation": "原文:learn the local custom"}]'::jsonb, '[{"word": "value", "cn": "重视;珍视"}, {"word": "capital", "cn": "首都;国都"}, {"word": "custom", "cn": "风俗;习俗"}]'::jsonb, 3, '9', 'U10');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Table Manners Around the World', 'Table manners are different around the world. In some countries, you are supposed to use chopsticks. In others, you use a knife and fork. In India, people often eat with their right hand, but you are not supposed to use your left hand. In China, it is impolite to stick your chopsticks into your food. In some Western countries, you are not supposed to put your elbows on the table. In Japan, it is polite to make noise when you eat noodles. So when you travel, remember: what is polite in one country may be rude in another. The best advice is to watch what others do.', '说明文', 107, '[{"q": "What are you supposed to use in some countries to eat?", "answer": "A", "options": ["Chopsticks.", "Your feet.", "A spoon only.", "Nothing."], "explanation": "原文:supposed to use chopsticks"}, {"q": "In India, which hand are you not supposed to use?", "answer": "A", "options": ["The left hand.", "The right hand.", "No hands.", "Both hands."], "explanation": "原文:not supposed to use your left hand"}, {"q": "What is impolite in China?", "answer": "B", "options": ["Using a fork.", "Sticking chopsticks into your food.", "Eating noodles.", "Bowing."], "explanation": "原文:impolite to stick your chopsticks into your food"}, {"q": "What is polite in Japan when eating noodles?", "answer": "A", "options": ["To make noise.", "To be silent.", "To stand up.", "To use a fork."], "explanation": "原文:polite to make noise when you eat noodles"}, {"q": "What is the best advice when you travel?", "answer": "D", "options": ["To bring food.", "To eat fast.", "To stay home.", "To watch what others do."], "explanation": "原文:watch what others do"}]'::jsonb, '[{"word": "manner", "cn": "礼仪;方式"}, {"word": "elbow", "cn": "肘;胳膊"}, {"word": "stick", "cn": "插;粘"}]'::jsonb, 3, '9', 'U10');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Yu Mei''s Letter from France', 'Dear Laura, How are you? I am an exchange student in France now, and I am learning a lot. At first, I made many mistakes with the customs. For example, in France, you are not supposed to put your bread on your plate. You are supposed to put it on the table! Also, when you have dinner, you are expected to keep both hands on the table. At home, I was taught the opposite. The biggest challenge is the food. There is so much of it! But my host family is very kind. They go out of their way to make me feel at home. Gradually, I am getting used to life here. Yours, Yu Mei', '记叙文', 116, '[{"q": "Where is Yu Mei an exchange student?", "answer": "A", "options": ["In France.", "In Japan.", "In the US.", "In China."], "explanation": "原文:exchange student in France"}, {"q": "Where are you supposed to put your bread in France?", "answer": "D", "options": ["On the floor.", "In your bag.", "On your plate.", "On the table."], "explanation": "原文:put it on the table"}, {"q": "Where are you expected to keep your hands during dinner?", "answer": "A", "options": ["On the table.", "In your pockets.", "Under the table.", "In your lap."], "explanation": "原文:keep both hands on the table"}, {"q": "What is Yu Mei''s biggest challenge?", "answer": "B", "options": ["The school.", "The food.", "The weather.", "The language."], "explanation": "原文:The biggest challenge is the food"}, {"q": "How does the host family treat Yu Mei?", "answer": "D", "options": ["They are angry.", "They ignore her.", "They are strict.", "They make her feel at home."], "explanation": "原文:make me feel at home"}]'::jsonb, '[{"word": "custom", "cn": "习俗"}, {"word": "gradually", "cn": "逐步地"}, {"word": "challenge", "cn": "挑战"}]'::jsonb, 3, '9', 'U10');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Welcome Guide for Exchange Students', 'WELCOME TO OUR SCHOOL! This guide will help you learn our customs. GREETINGS: When you meet a teacher, you are supposed to say "Good morning." It is polite to be friendly. ON TIME: You are expected to arrive at class on time. It is impolite to be late. IN CLASS: You are not supposed to use your phone. Please turn it off. AT LUNCH: You are supposed to wait in line. Do not push others. WITH FRIENDS: It is polite to share and help each other. If you are not sure what to do, just ask. We hope you will feel at home here. Enjoy your time with us!', '应用文', 109, '[{"q": "What does the guide help you learn?", "answer": "C", "options": ["The school''s history.", "The school''s food.", "The school''s customs.", "The school''s map."], "explanation": "原文:help you learn our customs"}, {"q": "What are you supposed to say to a teacher?", "answer": "B", "options": ["Hello there.", "Good morning.", "Nothing.", "Goodbye."], "explanation": "原文:supposed to say Good morning"}, {"q": "What is impolite according to the guide?", "answer": "D", "options": ["Being early.", "Sharing.", "Saying hello.", "Being late."], "explanation": "原文:impolite to be late"}, {"q": "What are you not supposed to do in class?", "answer": "A", "options": ["Use your phone.", "Ask questions.", "Listen.", "Take notes."], "explanation": "原文:not supposed to use your phone"}, {"q": "What should you do if you are not sure what to do?", "answer": "C", "options": ["Go home.", "Stay quiet.", "Just ask.", "Leave."], "explanation": "原文:just ask"}]'::jsonb, '[{"word": "custom", "cn": "习俗"}, {"word": "greet", "cn": "打招呼"}, {"word": "polite", "cn": "礼貌的"}]'::jsonb, 3, '9', 'U10');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U10', 'Customs in Different Countries', 'When you visit a foreign country, it is important to learn its (1)____. People greet each other in different (2)____. In some countries, you are (3)____ to shake hands. In Japan, you are supposed to (4)____. In some places, friends greet with a (5)____ on the cheek. Time also (6)____. In some countries, you are supposed to be on (7)____, and it is impolite to keep others (8)____. In other places, people are more (9)____ about time. Learning these customs helps you make a good first (10)____. Good manners are important everywhere.', 92, 3, '[{"q": "1", "answer": "D", "options": ["colors", "games", "prices", "customs"], "explanation": "习俗 customs"}, {"q": "2", "answer": "B", "options": ["price", "ways", "game", "color"], "explanation": "方式 ways"}, {"q": "3", "answer": "A", "options": ["supposed", "supposing", "supposes", "suppose"], "explanation": "be supposed to"}, {"q": "4", "answer": "C", "options": ["throw", "break", "bow", "lose"], "explanation": "鞠躬 bow"}, {"q": "5", "answer": "B", "options": ["price", "kiss", "color", "game"], "explanation": "亲吻 kiss"}, {"q": "6", "answer": "B", "options": ["breaks", "matters", "loses", "throws"], "explanation": "重要 matters"}, {"q": "7", "answer": "A", "options": ["time", "color", "price", "game"], "explanation": "准时 on time"}, {"q": "8", "answer": "A", "options": ["waiting", "running", "sleeping", "eating"], "explanation": "等候 keep waiting"}, {"q": "9", "answer": "C", "options": ["strict", "tired", "relaxed", "busy"], "explanation": "放松 relaxed"}, {"q": "10", "answer": "D", "options": ["price", "game", "color", "impression"], "explanation": "印象 impression"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U10', 'Maria''s Mistakes', 'Maria is an exchange (1)____ in the US. Last night, she had (2)____ at a friend''s house. She made some (3)____ because she did not know the customs. First, she arrived (4)____. In the US, you are supposed to be on (5)____. Then she started eating before everyone (6)____. You are supposed to (7)____ until everyone is ready. But her friend''s family was not (8)____ at her. They kindly helped her (9)____. By the end of the night, Maria felt more (10)____. She learned that customs are important.', 88, 3, '[{"q": "1", "answer": "D", "options": ["price", "game", "color", "student"], "explanation": "学生 student"}, {"q": "2", "answer": "B", "options": ["color", "dinner", "price", "game"], "explanation": "晚饭 dinner"}, {"q": "3", "answer": "D", "options": ["prices", "games", "colors", "mistakes"], "explanation": "错误 mistakes"}, {"q": "4", "answer": "B", "options": ["early", "late", "on", "at"], "explanation": "迟到 late"}, {"q": "5", "answer": "C", "options": ["price", "color", "time", "game"], "explanation": "准时 on time"}, {"q": "6", "answer": "A", "options": ["else", "game", "color", "price"], "explanation": "别人 everyone else"}, {"q": "7", "answer": "A", "options": ["wait", "throw", "lose", "break"], "explanation": "等待 wait"}, {"q": "8", "answer": "B", "options": ["glad", "mad", "happy", "kind"], "explanation": "生气 mad"}, {"q": "9", "answer": "A", "options": ["learn", "lose", "break", "throw"], "explanation": "学习 learn"}, {"q": "10", "answer": "C", "options": ["angry", "busy", "relaxed", "tired"], "explanation": "放松 relaxed"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U10', 'On Time or Relaxed?', 'People have different ideas (1)____ time. Teresa is from Colombia. She thinks it is (2)____ to be a little late. "We (3)____ people more than time," she says. If a friend is late, she does not get (4)____. Marc is from Switzerland. For him, being on (5)____ is very important. If you are (6)____ to dinner at seven, you are supposed to (7)____ at seven. Both ideas are fine in their own (8)____. The most important thing is to learn the local (9)____, so you do not make others feel (10)____.', 91, 3, '[{"q": "1", "answer": "B", "options": ["color", "about", "price", "game"], "explanation": "关于 about time"}, {"q": "2", "answer": "C", "options": ["bad", "rude", "OK", "wrong"], "explanation": "没关系 OK"}, {"q": "3", "answer": "A", "options": ["value", "lose", "throw", "break"], "explanation": "重视 value"}, {"q": "4", "answer": "A", "options": ["mad", "happy", "glad", "kind"], "explanation": "生气 mad"}, {"q": "5", "answer": "D", "options": ["price", "color", "game", "time"], "explanation": "准时 on time"}, {"q": "6", "answer": "B", "options": ["broken", "invited", "thrown", "lost"], "explanation": "被邀请 invited"}, {"q": "7", "answer": "B", "options": ["break", "arrive", "lose", "throw"], "explanation": "到达 arrive"}, {"q": "8", "answer": "C", "options": ["colors", "games", "countries", "prices"], "explanation": "国家 countries"}, {"q": "9", "answer": "D", "options": ["game", "color", "price", "custom"], "explanation": "习俗 custom"}, {"q": "10", "answer": "A", "options": ["uneasy", "happy", "proud", "glad"], "explanation": "不安 uneasy"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U10', 'Table Manners', 'Table manners are different around the (1)____. In some countries, you are supposed to use (2)____. In others, you use a knife and (3)____. In China, it is (4)____ to stick your chopsticks into your food. In some Western countries, you are not supposed to put your (5)____ on the table. In Japan, it is (6)____ to make noise when you eat noodles. So when you (7)____, remember that what is polite in one country may be (8)____ in another. The best (9)____ is to watch what others do. Then you will not (10)____ any mistakes.', 96, 3, '[{"q": "1", "answer": "D", "options": ["color", "price", "game", "world"], "explanation": "世界 world"}, {"q": "2", "answer": "A", "options": ["chopsticks", "prices", "colors", "games"], "explanation": "筷子 chopsticks"}, {"q": "3", "answer": "B", "options": ["price", "fork", "game", "color"], "explanation": "叉子 fork"}, {"q": "4", "answer": "A", "options": ["impolite", "kind", "polite", "nice"], "explanation": "不礼貌 impolite"}, {"q": "5", "answer": "B", "options": ["colors", "elbows", "prices", "games"], "explanation": "胳膊肘 elbows"}, {"q": "6", "answer": "D", "options": ["bad", "wrong", "rude", "polite"], "explanation": "礼貌 polite"}, {"q": "7", "answer": "C", "options": ["throw", "lose", "travel", "break"], "explanation": "旅行 travel"}, {"q": "8", "answer": "B", "options": ["nice", "rude", "polite", "kind"], "explanation": "粗鲁 rude"}, {"q": "9", "answer": "C", "options": ["game", "price", "advice", "color"], "explanation": "建议 advice"}, {"q": "10", "answer": "A", "options": ["make", "throw", "lose", "break"], "explanation": "犯错 make mistakes"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U10', 'A Letter from France', 'Dear Laura, I am an exchange student in France now. At first, I made many (1)____ with the customs. For example, in France, you are not (2)____ to put your bread on your plate. You put it on the (3)____! Also, you are (4)____ to keep both hands on the table during dinner. At home, I was taught the (5)____. The biggest (6)____ for me is the food. There is so much of it! But my host family is very (7)____. They go out of their way to make me feel at (8)____. (9)____, I am getting used to life here. I will write again (10)____. Yours, Yu Mei', 109, 3, '[{"q": "1", "answer": "B", "options": ["prices", "mistakes", "colors", "games"], "explanation": "错误 mistakes"}, {"q": "2", "answer": "A", "options": ["supposed", "supposes", "supposing", "suppose"], "explanation": "be supposed to"}, {"q": "3", "answer": "D", "options": ["game", "color", "price", "table"], "explanation": "桌子 table"}, {"q": "4", "answer": "A", "options": ["expected", "expecting", "expect", "expects"], "explanation": "be expected to"}, {"q": "5", "answer": "B", "options": ["price", "opposite", "same", "color"], "explanation": "相反 opposite"}, {"q": "6", "answer": "D", "options": ["game", "color", "price", "challenge"], "explanation": "挑战 challenge"}, {"q": "7", "answer": "B", "options": ["bad", "kind", "mad", "rude"], "explanation": "友好 kind"}, {"q": "8", "answer": "C", "options": ["price", "game", "home", "color"], "explanation": "家 at home"}, {"q": "9", "answer": "C", "options": ["Seldom", "Once", "Gradually", "Never"], "explanation": "逐渐 gradually"}, {"q": "10", "answer": "A", "options": ["soon", "late", "never", "slow"], "explanation": "很快 soon"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U10', 'Welcome Guide', 'Welcome to our school! This guide will help you learn our (1)____. When you meet a teacher, you are (2)____ to say "Good morning." It is (3)____ to be friendly. You are (4)____ to arrive at class on time. It is impolite to be (5)____. In class, you are not supposed to use your (6)____. Please turn it off. At lunch, you are supposed to wait in (7)____. With friends, it is polite to (8)____ and help each other. If you are not (9)____ what to do, just ask. We hope you will feel at (10)____ here. Enjoy your time with us!', 102, 3, '[{"q": "1", "answer": "A", "options": ["customs", "prices", "games", "colors"], "explanation": "习俗 customs"}, {"q": "2", "answer": "B", "options": ["supposing", "supposed", "supposes", "suppose"], "explanation": "be supposed to"}, {"q": "3", "answer": "C", "options": ["rude", "bad", "polite", "wrong"], "explanation": "礼貌 polite"}, {"q": "4", "answer": "D", "options": ["expect", "expecting", "expects", "expected"], "explanation": "be expected to"}, {"q": "5", "answer": "B", "options": ["on", "late", "at", "early"], "explanation": "迟到 late"}, {"q": "6", "answer": "A", "options": ["phone", "color", "game", "price"], "explanation": "手机 phone"}, {"q": "7", "answer": "B", "options": ["price", "line", "game", "color"], "explanation": "排队 in line"}, {"q": "8", "answer": "A", "options": ["share", "throw", "break", "lose"], "explanation": "分享 share"}, {"q": "9", "answer": "C", "options": ["happy", "tired", "sure", "busy"], "explanation": "确定 sure"}, {"q": "10", "answer": "D", "options": ["game", "price", "color", "home"], "explanation": "家 at home"}]'::jsonb, 6);
